self.window=self;
importScripts('../../castle-gen.js','../../castle-render.js','../../castle-vox.js');
onmessage=e=>{try{const start=performance.now(),frame={x:0,z:0,rot:0},meshes=[],models=[];let cells=0,actualCell=0;for(const parts of e.data.groups){if(e.data.engine==='ray'){const v=CastleVox.voxelizeSparse(parts,frame,e.data.cell*4,p=>p.col||[.7,.7,.6],()=>0);if(!v.coarse){models.push(null);continue;}cells+=v.coarse.length*64;actualCell=Math.max(actualCell,v.cvs/4);models.push({coarse:v.coarse,n:v.n,o:v.o,cvs:v.cvs,bricks:v.bricks,brickRows:v.brickRows,nb:v.nb,pal:v.pal});}else{const v=CastleVox.voxelize(parts,frame,e.data.cell,p=>p.col||[.7,.7,.6],()=>0),m=CastleVox.meshVox(v,frame,new CastleRender.Mesh());cells+=v.grid?.length||0;actualCell=Math.max(actualCell,v.vs||0);meshes.push({p:new Float32Array(m.p),n:new Float32Array(m.n),c:new Float32Array(m.c)});}}const transfer=e.data.engine==='ray'?models.filter(Boolean).flatMap(m=>[m.coarse.buffer,m.bricks.buffer,m.pal.buffer]):meshes.flatMap(m=>[m.p.buffer,m.n.buffer,m.c.buffer]);postMessage({token:e.data.token,engine:e.data.engine,meshes,models,cells,actualCell,ms:performance.now()-start},transfer);}catch(error){postMessage({token:e.data.token,error:error.stack||String(error)});}};
